        13'd7    : uw <= 47'h598068400081;   // sign extend the immediate into the data register
        13'd8    : uw <= 47'h598058400091;   // one register to another
        13'd9    : uw <= 47'h2540384000A0;   // take the displacement from the word after the instruction
        13'd10   : uw <= 47'h0850C84000B0;   // the branch base
        13'd11   : uw <= 47'h6812084000C0;   // ... plus the displacement
        13'd12   : uw <= 47'h0800004000D1;   // ... then wait for the pipe and decode
